const lockTurnsToExpire = `-- name: LockTurnsToExpire :many
select id from turns
where state = 'queued' and created_at < now(6) - interval ? microsecond
order by created_at, id
for update
`

func (q *Queries) LockTurnsToExpire(ctx context.Context, microseconds interface{}) ([]key.ID, error) {
	rows, err := q.db.QueryContext(ctx, lockTurnsToExpire, microseconds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []key.ID
	for rows.Next() {
		var id key.ID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockUnsentAttachments = `-- name: LockUnsentAttachments :many
select id, session_id, turn_id, position, name, media_type, size, created_by, created_at from attachments
where id in (/*SLICE:ids*/?) and session_id = ? and turn_id is null
for update
`

type LockUnsentAttachmentsParams struct {
	Ids       []key.ID
	SessionID key.ID
}

// Locks those of the attachments that are of the session and that no message
// carries, until the transaction ends.
func (q *Queries) LockUnsentAttachments(ctx context.Context, arg LockUnsentAttachmentsParams) ([]Attachment, error) {
	query := lockUnsentAttachments
	var queryParams []interface{}
	if len(arg.Ids) > 0 {
		for _, v := range arg.Ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(arg.Ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	queryParams = append(queryParams, arg.SessionID)
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Attachment
	for rows.Next() {
		var i Attachment
		if err := rows.Scan(
			&i.ID,
			&i.SessionID,
			&i.TurnID,
			&i.Position,
			&i.Name,
			&i.MediaType,
			&i.Size,
			&i.CreatedBy,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

